from collections import Counter

class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        if not s:
            return ''
        remaining = Counter(s)
        position = 0
        for i, char in enumerate(s):
            if char < s[position]:
                position = i
            remaining[char] -= 1
            if remaining[char] == 0:
                break
        char = s[position]
        return char + self.removeDuplicateLetters(s[position + 1:].replace(char, ''))
